function MetricsPanel({ teamId }) {
  const [data, setData] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    fetch('/api/metrics?team=' + teamId).then(r => r.json()).then(d => setData(d));
  });

  useEffect(() => {
    setFiltered(data.filter(m => m.name.includes(search)));
  }, [data, search]);

  return (<div><input onChange={e => setSearch(e.target.value)} />{filtered.map(m => <Row m={m} />)}</div>);
}
